update content_bodies set title = 'Okinawa Tourism: Latest Edition / Regular Distribution / Rainy Day Sightseeing: Naha City ''Arcade Shopping Street: May 2023'' #512', description = 'This video showcases a leisurely walk through the ''Naha Arcade Shopping Street'' along Kokusai Street, bustling with tourists during the Golden Week. It captures the vibrant atmosphere of the area, highlighting various attractions and shops. The video also mentions the renewal of the Makishi Public Market, providing viewers with insights into Okinawa''s local culture and tourism. The content is aimed at those interested in exploring Okinawa''s charm, whether on sunny or rainy days.' where id = 'WhG63iHLIBZIA_tNz2RTA';
