update content_bodies set title = 'Okinawa Tourism: Latest Update - Naha Airport in May 2023', description = 'This video showcases the bustling atmosphere of Naha Airport on the first day of the latter half of the Golden Week in 2023. It captures the lively scenes and activities at the airport, providing a glimpse into the travel experience in Okinawa during this popular holiday period.' where id = 'JJRX9QnY_134X4JqvsArS';
update content_bodies set title = '沖縄観光 日本最大の海カフェ『バンタカフェ』', description = '『星のや沖縄』に隣接する日本最大の海カフェ『バンタカフェ』は、豪華な見た目ながらスターバックスのように気軽に利用できるカフェです。この動画では、沖縄の各地をのんびりと散歩しながら紹介しており、地域の美しさや魅力を伝えています。' where id = 'n6F1Oi1wp_nax5EOZU1-6';
update content_bodies set title = 'Okinawa Tourism: Japan''s Largest Ocean Cafe ''Banta Cafe''', description = 'Located next to ''Hoshinoya Okinawa'', ''Banta Cafe'' is Japan''s largest ocean cafe. Despite its luxurious appearance, it is as accessible as a Starbucks. The video showcases various parts of Okinawa while taking a leisurely stroll, highlighting the beauty and charm of the region.' where id = 'rLWEUsxMrdQzZ5qx6VDro';
